#!/usr/bin/env python3
import os, re, sys, collections

ROOT = sys.argv[1]
start = sys.argv[2]
targets = set(sys.argv[3].split(','))
search_dirs = [
    'include', 'include/uapi', 'arch/x86/include', 'arch/x86/include/uapi',
    'arch/x86/include/generated', 'include/generated', '.',
]
inc_re = re.compile(r'^\s*#\s*include\s*[<"]([^>"]+)[>"]')

def resolve(name):
    for d in search_dirs:
        p = os.path.join(ROOT, d, name)
        if os.path.isfile(p):
            return p
    return None

def includes(path):
    out = []
    try:
        with open(path, errors='ignore') as f:
            for line in f:
                m = inc_re.match(line)
                if m:
                    out.append(m.group(1))
    except OSError:
        pass
    return out

start_path = resolve(start) or os.path.join(ROOT, start)
visited = set()
q = collections.deque([start_path])
parent = {start_path: None}
found = {}
depth = {start_path: 0}
while q:
    p = q.popleft()
    if p in visited:
        continue
    visited.add(p)
    base = os.path.relpath(p, ROOT)
    if os.path.basename(base) in targets:
        found[base] = parent.get(p)
    if depth[p] > 40:
        continue
    for name in includes(p):
        rp = resolve(name)
        if rp and rp not in visited:
            parent.setdefault(rp, p)
            depth[rp] = depth[p] + 1
            q.append(rp)
print("visited:", len(visited))
for t, par in found.items():
    print("FOUND", t, "via", os.path.relpath(par, ROOT) if par else None)
if not found:
    print("NOT FOUND")

